    $('#addPin').onclick=()=>{setView('map');setTool('note');toast('Tap the map to place your pin.');};$('#saveMapNotes').onclick=()=>{change(()=>map.notes=$('#mapNotes').value);toast('Map instructions saved.');};
    if(!map.markers.length)$('#notesList').innerHTML='<div class="empty">Pin the exact tile you want to talk about.</div>';
    map.markers.forEach((n,i)=>{const el=document.createElement('div');el.className='note-card';el.tabIndex=0;el.setAttribute('role','button');el.innerHTML=`<strong><span style="color:${markerColors[n.kind]||markerColors.note}">● ${i+1}</span> ${esc(n.title)}</strong><small>${esc(n.kind)} · tile ${n.x}, ${n.y}</small><p>${esc(n.text)}</p>`;el.onclick=()=>{selection={kind:'marker',id:n.id};if(n.npc||n.rom?.type==='npc')authorTools.editPlaced(n);else if(n.runtime?.action==='scene')sceneUI.edit(n);else if(n.runtime?.action==='sequence')eventsUI.edit(n);else markerDialog(n.x,n.y,n);};el.onkeydown=e=>{if(e.key==='Enter')el.click();};$('#notesList').append(el);});
