function tileCategory(a){return a.rom?'ROM tiles':a.category?.startsWith('Objects')?'Objects':a.category==='Object sources'?'Object sources':a.category==='Smart terrain'?'Smart terrain':/interior|room|furniture|bed|kitchen|wall|floor|office|shop/i.test(a.name)?'Interiors':/tree|garden|forest|flower|grass|park/i.test(a.name)?'Nature':/water|sea|ocean|coral|river/i.test(a.name)?'Water':/cave|moon|rock|mountain|cliff|volcano|desert/i.test(a.name)?'Caves & rock':/house|building|roof|city|town|gate/i.test(a.name)?'Buildings & towns':a.data?'Imported':'Mixed sheets';}
