function setTool(tool,{follow=true}={}){
  if(pointers.size)cancelGesture();
  if(sceneUI?.state.pending&&!['scenePlace','sceneArea','scenePath','sceneWarp'].includes(tool)){sceneUI.state.pending=null;sceneUI.flow();}
  if(authorTools?.state.pendingActor&&tool!=='actorPlace')authorTools.state.pendingActor=null;
  if(mapCrop?.state.active&&tool!=='crop'){mapCrop.state.active=false;mapCrop.state.rect=null;mapCrop.flow();}
  if(mapLinks?.state.pending&&!['link','linkTarget'].includes(tool)){mapLinks.state.pending=null;mapLinks.flow();}
  if(world?.state.play&&tool!=='play'){world.state.play=null;$('#playDock').hidden=true;}
  if(world&&tool!=='portal')world.state.pendingPortal=null;
  const rawTools=['brush','fill','rect','pick'];if(rawTools.includes(tool)&&!rawTools.includes(activeTool)){if(tileBrush&&asset(tileBrush.assetId))brush=clone(tileBrush);selectedPrefab=null;}if(tool==='stamp'&&activeTool!=='stamp'&&stampBrush&&asset(stampBrush.assetId)){brush=clone(stampBrush);selectedPrefab=stampPrefab;}if(tool==='texture'&&textureBrush)brush=clone(textureBrush);
  activeTool=tool;selection=null;hoverTile=null;workspace='map';
  if(tool==='stamp')activeLayer='objects';if(tool==='terrain')activeLayer=smart.terrains().find(t=>t.id===smart.state.terrainId)?.paintLayer==='details'?'details':'ground';if(tool==='room'||tool==='interior')activeLayer='ground';
  toolbox?.follow(tool);
  if(follow){toolContext=tool==='erase'?'tiles':toolPanel(tool,toolContext);setPanel(toolContext,!$('#panel').classList.contains('closed'));}
  updateChrome();requestDraw();
}

function setView(next){if(next===view)return;if(pointers.size)cancelGesture();if(next==='world'){if(mapCrop?.state.active){mapCrop.state.active=false;mapCrop.flow();activeTool='move';}if(world?.state.play){world.state.play=null;$('#playDock').hidden=true;activeTool='move';}}if(view==='map')cameraByMap.set(m().id,{...cam});view=next;protectMapImages();selection=null;hoverTile=null;if(next==='map'&&cameraByMap.has(m().id))cam={...cameraByMap.get(m().id)};else fit();updateChrome();requestDraw();}
function useROMTiles(map,force=false){const id=map.rom?.atlasId;if(!id||!asset(id)||(!force&&!asset(brush?.assetId)?.rom))return;tileLibraryMode='source';const counts=new Map();for(const t of map.layers.ground)if(t?.a===id){const key=t.sx+','+t.sy;counts.set(key,(counts.get(key)||0)+1);}const key=[...counts].sort((a,b)=>b[1]-a[1])[0]?.[0]||'0,0';const[sx,sy]=key.split(',').map(Number);brush={assetId:id,sx,sy,cols:1,rows:1,tileSize:16};activeLayer='ground';activeTool='brush';toolContext='tiles';tileBrush=clone(brush);assetFilter='';}
function switchMap(id,preservePlay=false){if(pointers.size)cancelGesture();if(!project.maps.some(m=>m.id===id))return;if(mapCrop?.state.active){mapCrop.state.active=false;mapCrop.flow();}if(world?.state.play&&!preservePlay)world.stopPlay();if(view==='map')cameraByMap.set(m().id,{...cam});project.activeMapId=id;view='map';protectMapImages();selection=null;hoverTile=null;if(phone())setPanel(activePanel,false);useROMTiles(m());if(mapLinks?.state.pending){const p=mapLinks.state.pending;if(['target','confirm'].includes(p.stage)&&p.target!==id){p.target=id;p.stage='target';delete p.draft[p.end];}activeTool=p.stage==='from'?'link':'linkTarget';toolContext='connections';mapLinks.flow();}cam=cameraByMap.has(id)?{...cameraByMap.get(id)}:{x:0,y:0,scale:1};if(!cameraByMap.has(id))fit();markDirty();refresh();loadMapImages(m()).then(requestDraw).catch(showError);}

