  const run=async(fn,name)=>{busy(true,'Exporting…');$$('#dialogBody button').forEach(b=>b.disabled=true);$('#exportProgress').textContent='Preparing your file…';try{await persist();const blob=await fn();readyFile(blob,name);}catch(e){showError(e);$$('#dialogBody button').forEach(b=>b.disabled=false);if($('#exportProgress'))$('#exportProgress').textContent=e.message;}finally{busy(false);}};
