function paintBrushArea(tool,x,y){
  const radius=toolbox?.state.radius||1;
  for(let dy=1-radius;dy<radius;dy++)for(let dx=1-radius;dx<radius;dx++)if(dx*dx+dy*dy<radius*radius){const xx=x+dx,yy=y+dy;if(!inBounds(m(),xx,yy))continue;if(tool==='terrain'){smart.paint(activeLayer,xx,yy);invalidateMapArt(m().id,activeLayer,{x0:xx-1,y0:yy-1,x1:xx+1,y1:yy+1});}else paintAt(xx,yy);}
}
