 modal('Export an edited GBA ROM',`<p>${maps.length} linked map${maps.length===1?'':'s'} and ${gameChanges} game/sprite edits will be checked against <b>${esc(romSession.reader.filename)}</b>. Your source file stays intact.</p><label class="check"><input id="staticRomArt" type="checkbox" ${maps.some(m=>m.generator?.version===3)?'checked':''}> Use static tiles on edited maps to free graphics space</label><p class="hint-line">Recommended for generated settlements. Turn this off to preserve source tile animation. If new artwork needs more space, static mode packs both tile banks and freezes their animation on the edited maps. GBA palettes may change some imported colours; the next screen previews the actual exported art.</p><p>Buildings, linked interiors, walls, walking and jump rules, HM objects, Flash, portals, events and opening gates are compiled. Planning notes and reference images stay in the project.</p><p id="romCompileProgress" class="hint-line"></p>`,async()=>{const staticArtwork=$('#staticRomArt').checked,progress=s=>{if($('#romCompileProgress'))$('#romCompileProgress').textContent=s;};busy(true,'Compiling ROM…');try{await persist();const result=await buildRom(project,romSession.reader,{sourceId:romSession.id,renderMap:renderForRom,rasterTimeline:renderNativeOpening,wallStyles:world.walls(),staticArtwork,gateRedrawSpecial:discoverGateRedraw(romSession.reader,{sourceSha256:romSession.id})?.index??null,progress});progress('Checking exported map data…');const check=await new GbaMaps(result.bytes,'Export validation').discover();for(const report of result.reports){const map=check.byKey(report.key);if(!map)throw Error('The exported map table did not reopen correctly.');}showRomReview(result,check);return false;}finally{busy(false);}},'Compile & review');
