 if(report){const candidates=[];for(let y=0;y<map.height;y++)for(let x=0;x<map.width;x++){const rule=movementAt(map,x,y);if(rule.collision||waterAt(map,x,y)||ledgeAt(map,x,y)||map.markers.some(n=>n.x===x&&n.y===y)||project.links.some(l=>l.runtime&&[l.from,l.to].some(e=>e.mapId===map.id&&e.x===x&&e.y===y)))continue;candidates.push({x,y});}const p=world.state.play?.mapId===map.id?world.state.play:{x:map.width/2,y:map.height/2};candidates.sort((a,b)=>Math.abs(a.x-p.x)+Math.abs(a.y-p.y)-Math.abs(b.x-p.x)-Math.abs(b.y-p.y));if(candidates.length){const[bank,index]=report.key.split('.').map(Number);target={bank,index,...candidates[0],name:map.name};}}
