async function pickVisibleTile(t,screen){
 const map=m(),mapId=map.id,w=worldPoint(screen),px=clamp(Math.floor(w.x-t.x*16),0,15),py=clamp(Math.floor(w.y-t.y*16),0,15),choices=[];
 await loadMapImages(map);if(m().id!==mapId)return;
 function candidate(label,layer,draw,tile=null){const c=document.createElement('canvas');c.width=c.height=16;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;draw(ctx);if(ctx.getImageData(px,py,1,1).data[3]<16)return;choices.push({label,layer,canvas:c,tile});}
 const grid=layer=>{if(!visible[layer])return;const tile=getTile(map,layer,t.x,t.y);if(!tile)return;const im=imageNow(tile.a);if(im)candidate(layer[0].toUpperCase()+layer.slice(1),layer,c=>c.drawImage(im,tile.sx,tile.sy,tile.size,tile.size,0,0,16,16),tile);};
 grid('overhead');
 if(visible.objects){
  candidate('Gate artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);drawGates(c,map);});candidate('Wall artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);drawWalls(c,map);});
  candidate('Field object artwork','objects',c=>{c.translate(-t.x*16,-t.y*16);fieldTools?.draw(c,map);});
  for(const o of objectDrawOrder(map).reverse())if(t.x+1>o.x&&t.y+1>o.y&&t.x<o.x+o.w&&t.y<o.y+o.h&&o.opacity!==0)candidate(o.name||'Stamped object','objects',c=>drawObject(c,{...o,x:o.x-t.x,y:o.y-t.y}));
 }
 grid('objects');grid('details');grid('ground');
 if(!choices.length){toast('No visible artwork at this pixel.');return;}
 const apply=async choice=>{if(m().id!==mapId)return;const tile=choice.tile;if(tile)choosePaintTile({assetId:tile.a,sx:tile.sx,sy:tile.sy,cols:1,rows:1,tileSize:tile.size,...(tile.movementMode?{movementMode:tile.movementMode}:{}),...(tile.movementBehavior!==undefined?{movementBehavior:tile.movementBehavior}:{})},choice.label,choice.layer);else{const id=await rememberArtwork(choice.canvas,choice.label+' · picked tile');choosePaintTile({assetId:id,sx:0,sy:0,cols:1,rows:1,tileSize:16},choice.label,choice.layer);}$('#dialog').close();collapsePanel();};
 if(choices.length===1){await apply(choices[0]);return;}
 modal('Pick visible artwork',`<p>Several layers meet here. The top visible piece is first. Choose the artwork you meant; transparent pixels are skipped.</p><div class="pick-choices">${choices.map((c,i)=>`<button type="button" data-pick-choice="${i}"><img src="${c.canvas.toDataURL('image/png')}" alt=""><span>${esc(c.label)}${i===0?' · top visible':''}</span></button>`).join('')}</div>`);
 $$('[data-pick-choice]').forEach(b=>b.onclick=()=>apply(choices[+b.dataset.pickChoice]).catch(showError));
}
